// Composition
function Layout({ header, content }) {
  return (
    <>
      {header}
      {content}
    </>
  );
}

function App() {
  return (
    <Layout
      header={<h1>Header</h1>}
      content={<p>Main Content</p>}
    />
  );
}

// React generally prefers composition
// over component inheritance.

function Button({ text, onClick, disabled = false }) {
  return (
    <button onClick={onClick} disabled={disabled}>
      {text}
    </button>
  );
}

